`timescale 1ns/1ps

// 模块名称：soc_ram
// 功能与设计思路：
//   本模块实现 64KB (16384 字) 片上同步双端口静态存储器，综合推断为 FPGA 原生专用块 RAM (DRM)。
//   1. 端口 A：指令读取端，供 I-Cache 突发重填或 CPU 取指直接读取。
//   2. 端口 B：数据读写端，供 D-Cache 读写或 MMIO 外设事务访问，支持 4 位字节写选通掩码。
//   3. 固件预置：由构建脚本自动将编译生成的机器码内联至 initial 块中，实现上电自启动。

module soc_ram #(
  parameter integer RAM_WORDS = 16384
)(
  input  wire        clk,
  input  wire        reset,
  // 端口 A：指令端 (I-Cache)
  input  wire        im_valid,
  output reg         im_ready,
  input  wire [31:0] im_addr,
  output reg  [31:0] im_data,
  // 端口 B：数据端 (D-Cache)
  input  wire        dm_valid,
  output reg         dm_ready,
  input  wire        dm_write,
  input  wire [3:0]  dm_strb,
  input  wire [31:0] dm_addr,
  input  wire [31:0] dm_wdata,
  output reg  [31:0] dm_data
);

  // 统一 RAM 存储阵列
  reg [31:0] ram[0:RAM_WORDS-1];

  initial begin
    // 完整固件：demo；由 build.py 自动编译并同步内联生成
    // 64 KiB RAM 逐字显式初始化；每个地址均有明确定义，供 FPGA 综合上电即行
