  // 【时序逻辑：双端口同步读与字节使能写】
  // 数据阵列严格采用时钟上升沿同步读写，绝不加入全局异步复位，
  // 满足紫光同创 PDS 综合器对专有 DRM (Dedicated Block RAM) 块的硬核推断模板。
  always @(posedge clk) begin
    // 端口 A 同步读：I-Cache 突发取指
    if (im_valid && !im_ready)
      im_data <= ram[im_addr >> 2];

    // 端口 B 同步读写：D-Cache 访存与直写
    if (dm_valid && !dm_ready) begin
      dm_data <= ram[dm_addr >> 2];
      if (dm_write) begin
        // 4 位字节写掩码精确寻址写入
        if (dm_strb[0]) ram[dm_addr >> 2][7:0]   <= dm_wdata[7:0];
        if (dm_strb[1]) ram[dm_addr >> 2][15:8]  <= dm_wdata[15:8];
        if (dm_strb[2]) ram[dm_addr >> 2][23:16] <= dm_wdata[23:16];
        if (dm_strb[3]) ram[dm_addr >> 2][31:24] <= dm_wdata[31:24];
      end
    end
  end

  // 【总线握手应答逻辑】：
  // 采用 1 拍同步应答握手机制：请求有效的下一拍拉高 ready，并随之后撤，
  // 保证上层 Cache 控制器能够稳定采样到数据输出。
  always @(posedge clk) begin
    if (reset) begin
      im_ready <= 1'b0;
      dm_ready <= 1'b0;
    end else begin
      im_ready <= im_valid && !im_ready;
      dm_ready <= dm_valid && !dm_ready;
    end
  end

endmodule
